@push('styles')
<style>
.planning-page{color:#18385c;font-size:12px}.planning-toolbar,.planning-panel{background:#fff;border:1px solid #d5e0ee;border-radius:7px;box-shadow:0 2px 6px rgba(24,56,92,.04);padding:18px;margin-bottom:16px}.planning-topline{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:18px}.planning-eyebrow{text-transform:uppercase;letter-spacing:.1em;font-size:10px;font-weight:700;color:#6481a5;margin-bottom:5px}.planning-page h2{font-size:14px;font-weight:700;margin:0}.planning-page h3{font-size:13px;font-weight:700;margin:0}.planning-help{font-size:11px;color:#7d8ba1;margin-top:5px}.planning-filter{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr)) auto auto auto;gap:10px;align-items:end}.planning-field label{display:block;font-size:11px;font-weight:600;margin-bottom:6px}.planning-field input,.planning-field select,.planning-field textarea{width:100%;min-height:36px;border:1px solid #cedaeb;border-radius:4px;background:#fff;padding:7px 9px;color:#18385c;font:inherit}.planning-field input[readonly]{background:#edf2f7}.planning-field small{display:block;font-size:10px;color:#7d8ba1;margin-top:6px}.planning-btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid #cbd9ec;border-radius:4px;background:#fff;color:#18385c;padding:8px 13px;min-height:35px;font-size:11px;font-weight:600;text-decoration:none;white-space:nowrap;cursor:pointer}.planning-btn:hover{background:#edf3fb}.planning-btn-primary{background:#19385e;border-color:#19385e;color:#fff}.planning-btn-primary:hover{background:#244c7a}.planning-btn:focus-visible{outline:2px solid #3b82f6;outline-offset:2px}.planning-grid{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:12px;margin-bottom:16px}.planning-stat{border:1px solid #d5e0ee;border-top:3px solid #6d8bac;border-radius:6px;background:#fff;padding:14px;box-shadow:0 2px 6px rgba(24,56,92,.04)}.planning-stat p{font-size:11px;color:#7d8ba1;margin:0 0 8px}.planning-stat strong{font-size:20px;display:block;font-variant-numeric:tabular-nums;line-height:1.2}.planning-stat small{display:block;font-size:10px;color:#7d8ba1;margin-top:8px}.planning-stat-good{border-top-color:#00a96b}.planning-stat-buy{border-top-color:#e6b700;background:#fffcf0}.planning-stat-short{border-top-color:#dc2626;background:#fff5f5}.planning-panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:15px}.planning-scroll{overflow-x:auto}.planning-table{width:100%;border-collapse:collapse;font-size:11px}.planning-table th{background:#eaf0f7;color:#18385c;text-align:left;font-weight:700;padding:11px 9px;border:1px solid #d2deec;white-space:nowrap}.planning-table td{padding:12px 9px;border:1px solid #dce4ee;background:#f9fafc;vertical-align:middle;font-variant-numeric:tabular-nums}.planning-table .planning-number{text-align:right;white-space:nowrap}.planning-table .planning-shortage{background:#fff3f3;color:#d71920;font-weight:700}.planning-table .planning-buy{background:#fcf7e3;color:#795b00;font-weight:700}.planning-table .planning-empty{background:#fff;color:#7d8ba1;text-align:center;padding:24px}.planning-table .planning-actions{display:flex;gap:6px;align-items:center;white-space:nowrap}.planning-table .planning-muted{color:#7d8ba1;font-size:10px}.planning-inputs{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:14px;background:#f7f9fc;padding:16px;border:1px solid #d9e3ef;border-radius:5px}.planning-save{display:flex;justify-content:flex-end;margin-top:16px}.planning-version{background:#edf3fb;border-radius:12px;padding:4px 9px;font-size:10px;font-weight:700}.planning-tabs{display:flex;gap:8px;margin-bottom:14px}.planning-tabs a{scroll-margin-top:90px}.planning-page details>summary{cursor:pointer;font-weight:600;list-style:revert}.planning-page details>div{margin-top:16px}.planning-check{display:flex;align-items:center;gap:6px;font-size:11px;min-height:36px;white-space:nowrap}.planning-alert{padding:12px;border:1px solid #fecaca;background:#fff3f3;color:#b91c1c;border-radius:5px;margin-bottom:14px}.planning-table .row-actions{display:flex;gap:6px}.planning-page .dt-container{font-size:11px}.planning-page .dt-container .dt-layout-row{padding-left:0!important;padding-right:0!important}.planning-page .dt-container table.dataTable th,.planning-page .dt-container table.dataTable td{padding:11px 9px!important}.planning-page .dt-container .planning-shortage{color:#d71920!important;background:#fff3f3!important}.planning-page .dt-container .planning-buy{color:#795b00!important;background:#fcf7e3!important}
.planning-field input,.planning-field select{box-sizing:border-box;height:40px!important;min-height:40px!important}.planning-field .select2-container{width:100%!important;height:40px!important;min-height:40px!important}.planning-field .select2-container .select2-selection--single{height:40px!important;min-height:40px!important;border:1px solid #cedaeb!important;border-radius:6px!important;background:#fff!important}.planning-field .select2-container .select2-selection__rendered{height:38px!important;padding:0 34px 0 10px!important;color:#18385c!important;line-height:38px!important}.planning-field .select2-container .select2-selection__arrow{top:0!important;right:6px!important;width:24px!important;height:38px!important}
.planning-page .delivery-flag{display:inline-flex;border:1px solid transparent;border-radius:999px;padding:4px 8px;font-size:10px;font-weight:800;line-height:1}.planning-page .delivery-flag-planned{background:#eef2ff;border-color:#c7d2fe;color:#4338ca}.planning-page .delivery-flag-in_transit{background:#eff6ff;border-color:#bfdbfe;color:#1d4ed8}.planning-page .delivery-flag-partially_received{background:#fffbeb;border-color:#fde68a;color:#a16207}.planning-page .delivery-flag-received{background:#ecfdf5;border-color:#a7f3d0;color:#047857}.planning-page .delivery-flag-cancelled{background:#fef2f2;border-color:#fecaca;color:#b91c1c}
@media(max-width:1200px){.planning-filter{grid-template-columns:repeat(2,minmax(140px,1fr))}.planning-grid{grid-template-columns:repeat(3,minmax(120px,1fr))}.planning-inputs{grid-template-columns:repeat(2,minmax(150px,1fr))}}
@media(max-width:600px){.planning-grid{grid-template-columns:repeat(2,minmax(100px,1fr))}.planning-inputs,.planning-filter{grid-template-columns:1fr}.planning-topline{align-items:flex-start}.planning-panel,.planning-toolbar{padding:12px}.planning-stat strong{font-size:18px}}
</style>
@endpush
